    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Antares_Arx::KEY_A_E_B(PARAMS_SEED);

    KeyDiffuse_A_A_E(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Antares_Arx::KEY_A_E_C(PARAMS_SEED);

    //
    // src: [$water]
